package in.guvi.fraud.web;
import in.guvi.fraud.dao.TransactionDao;import in.guvi.fraud.service.MlFraudModel;import in.guvi.fraud.db.Database;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.*;import java.sql.*;
@WebServlet("/admin") public class AdminServlet extends RoleServlet{
 protected void doGet(HttpServletRequest q,HttpServletResponse p)throws IOException,ServletException{if(!require(q,p,"admin"))return;try{TransactionDao d=(TransactionDao)getServletContext().getAttribute("dao");q.setAttribute("tx",d.list(200,true));q.setAttribute("total",d.count(""));q.setAttribute("flagged",d.count("WHERE decision<>'APPROVED'"));q.setAttribute("reviewed",d.count("WHERE reviewed=TRUE"));q.setAttribute("check",d.setting("check",30));q.setAttribute("review",d.setting("review",60));q.setAttribute("rows",((MlFraudModel)getServletContext().getAttribute("model")).rows());q.getRequestDispatcher("/admin.jsp").forward(q,p);}catch(Exception e){throw new ServletException(e);}}
 protected void doPost(HttpServletRequest q,HttpServletResponse p)throws IOException,ServletException{if(!require(q,p,"admin"))return;try{TransactionDao d=(TransactionDao)getServletContext().getAttribute("dao");String a=q.getParameter("action");if("settings".equals(a)){int c=Integer.parseInt(q.getParameter("check")),r=Integer.parseInt(q.getParameter("review"));if(c<1||r>100||r<=c)throw new IllegalArgumentException("Require 1 <= CHECK < REVIEW <= 100");d.setting("check",c);d.setting("review",r);}else if("review".equals(a)){String n=q.getParameter("note");d.review(Long.parseLong(q.getParameter("id")),n==null?"Reviewed":n.substring(0,Math.min(500,n.length())));}else if("retrain".equals(a)){((MlFraudModel)getServletContext().getAttribute("model")).train();}p.sendRedirect(q.getContextPath()+"/admin?updated=1");}catch(IllegalArgumentException e){p.sendError(400,e.getMessage());}catch(Exception e){throw new ServletException(e);}}
}
